import numpy as np
from scipy.optimize import minimize, differential_evolution

xs = np.array([0.2, 0.5, 1.0, 2.0, 5.0, 10.0])
ys = np.array([0.2, 0.5, 1.0, 2.0, 5.0, 10.0])

def residual(params, form):
    if form == 'ca':  # f(x) = c/x^a
        c, a = params
        f = lambda x: c / x**a
    elif form == 'cxa':  # f(x) = c/(x+a)
        c, a = params
        f = lambda x: c/(x+a) if x+a>1e-9 else 1e9
    elif form == 'exp':  # f(x) = c*exp(-a*x)
        c, a = params
        f = lambda x: c*np.exp(-a*x)
    elif form == 'pow':  # f(x) = c*x^a (a<0)
        c, a = params
        f = lambda x: c*x**a
    err = 0
    for x in xs:
        for y in ys:
            try:
                lhs = f(x)
                ffx = f(f(x))
                fffx = f(ffx)
                rhs = f(fffx + y) + f(x*f(y))*f(x+y)
                err += (lhs - rhs)**2
            except:
                err += 1e6
    return err

for form in ['ca', 'cxa', 'exp', 'pow']:
    if form == 'ca' or form == 'pow':
        bounds = [(0.01, 10), (-3, 3)]
    elif form == 'cxa':
        bounds = [(0.01, 10), (-1, 5)]
    else:
        bounds = [(0.01, 10), (0.01, 5)]
    result = differential_evolution(lambda p: residual(p, form), bounds, seed=42, maxiter=200, tol=1e-12)
    print(f'{form}: params={result.x}, residual={result.fun:.2e}')
